  function runNetworkCmd(key, btn) {
    const d = NETWORK_CMDS[key];
    if (!d) return;
    const lines = d.cmd.split('\n');
    document.getElementById('netCmd').textContent = lines[0];
    let extra = '';
    if (lines.length > 1) {
      extra = lines.slice(1).map(l => '<span class="ld-prompt">devops@server:~$</span> ' + l).join('\n') + '\n';
    }
    document.getElementById('netOutput').innerHTML = extra + d.output;
    document.getElementById('netSyntax').innerHTML = d.syntax || lines[0];
    document.getElementById('netDoes').innerHTML = d.does;
    document.getElementById('netWhere').innerHTML = d.where;
    document.querySelectorAll('#tab-networking .ld-pill').forEach(p => p.classList.remove('active'));
    if (btn) btn.classList.add('active');
  }

