  function runSshCmd(key, btn) {
    const d = SSH_CMDS[key];
    if (!d) return;
    const runsArea = document.getElementById('sshRunsArea');
    if (d.runs && d.runs.length) {
      renderCmdRuns(d.runs, runsArea);
    } else {
      // legacy shape — single cmd/output pair, not yet migrated to runs:[]
      const lines = d.cmd.split('\n');
      let extra = '';
      if (lines.length > 1) {
        extra = lines.slice(1).map(l => '<span class="ld-prompt">devops@server:~$</span> ' + l).join('\n') + '\n';
      }
      renderCmdRuns([{ cmd: lines[0], output: extra + d.output }], runsArea);
    }
    document.getElementById('sshSyntax').innerHTML = d.syntax || (d.runs ? d.runs[0].cmd.split('\n')[0] : d.cmd.split('\n')[0]);
    document.getElementById('sshDoes').innerHTML = d.does;
    document.getElementById('sshWhere').innerHTML = d.where;
    const sshBdList = document.getElementById('sshBreakdownList');
    if (sshBdList) {
      sshBdList.innerHTML = (d.breakdown && d.breakdown.length)
        ? d.breakdown.map(b => `<div class="sl-breakdown-item"><span class="sl-breakdown-term">${b.term}</span><span class="sl-breakdown-desc">${b.desc}</span></div>`).join('')
        : '<span class="dim">No further breakdown needed for this one.</span>';
    }
    const sshWhyEl = document.getElementById('sshWhyUseful');
    if (sshWhyEl) sshWhyEl.innerHTML = d.whyUseful || '<span class="dim">—</span>';
    document.querySelectorAll('#tab-shell .ld-pill').forEach(p => p.classList.remove('active'));
    if (btn) btn.classList.add('active');
  }

