  function runDockerCmd(key, btn) {
    const d = DOCKER_CMDS[key];
    if (!d) return;
    const runsArea = document.getElementById('dockerRunsArea');
    if (d.runs && d.runs.length) {
      renderCmdRuns(d.runs, runsArea);
    } else {
      // legacy shape — single cmd/output pair, not yet migrated to runs:[]
      const lines = d.cmd.split('\n');
      let extra = '';
      if (lines.length > 1) {
        extra = lines.slice(1).map(l => '<span class="ld-prompt">devops@server:~$</span> ' + l).join('\n') + '\n';
      }
      renderCmdRuns([{ cmd: lines[0], output: extra + d.output }], runsArea);
    }
    document.getElementById('dockerSyntax').innerHTML = d.syntax || (d.runs ? d.runs[0].cmd.split('\n')[0] : d.cmd.split('\n')[0]);
    document.getElementById('dockerDoes').innerHTML = d.does;
    document.getElementById('dockerWhere').innerHTML = d.where;
    const dockerBdList = document.getElementById('dockerBreakdownList');
    if (dockerBdList) {
      dockerBdList.innerHTML = (d.breakdown && d.breakdown.length)
        ? d.breakdown.map(b => `<div class="sl-breakdown-item"><span class="sl-breakdown-term">${b.term}</span><span class="sl-breakdown-desc">${b.desc}</span></div>`).join('')
        : '<span class="dim">No further breakdown needed for this one.</span>';
    }
    const dockerWhyEl = document.getElementById('dockerWhyUseful');
    if (dockerWhyEl) dockerWhyEl.innerHTML = d.whyUseful || '<span class="dim">—</span>';
    document.querySelectorAll('#tab-dockerdevops .ld-pill').forEach(p => p.classList.remove('active'));
    if (btn) btn.classList.add('active');
  }

